<template><div class="app-container"><el-card><template #header>{{props.title}}</template><el-form :inline="true" :model="query"><el-form-item v-for="f in props.queryFields" :key="f.prop" :label="f.label"><el-input v-model="query[f.prop]" @keyup.enter="search"/></el-form-item><el-button type="primary" @click="search">查询</el-button></el-form><el-table v-loading="loading" :data="rows" border><el-table-column type="index" width="55"/><el-table-column v-for="c in props.columns" :key="c.prop" :prop="c.prop" :label="c.label"><template #default="s">{{display(s.row[c.prop])}}</template></el-table-column><el-table-column label="操作"><template #default="s"><el-button link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table><Pagination v-show="total>0" v-model:page="page.current" v-model:limit="page.size" :total="total" @pagination="load"/></el-card></div></template>
<script setup>import{pageConfigs,toCrudProps}from'@/views/pageConfig';import{useCrudPage}from'@/views/useCrudPage';import{pageApi}from'./api';const props=toCrudProps(pageConfigs.token,pageApi,{fetch:'tokens',remove:'deleteToken'});const{loading,rows,total,query,page,display,load,search,remove}=useCrudPage(props)</script>
